import{_ as r,o as t,c as a,a5 as l}from"./chunks/framework.QnCkLuYX.js";const i="/assets/unsaved-diff.D71dG23X.png",s="/assets/reimport-review.CDchByRp.png",n="/assets/export-wizard.CpkcCoNj.png",m=JSON.parse('{"title":"保存与导出","description":"","frontmatter":{},"headers":[],"relativePath":"07-saving-and-exporting.md","filePath":"zh-CN/07-saving-and-exporting.md"}'),e={name:"07-saving-and-exporting.md"};function g(d,o,p,h,c,S){return t(),a("div",null,[...o[0]||(o[0]=[l('<h1 id="保存与导出" tabindex="-1">保存与导出 <a class="header-anchor" href="#保存与导出" aria-label="Permalink to &quot;保存与导出&quot;">​</a></h1><p>安全保存工作，并生成可交付的 CSV、XLSX、SRT 或 ASS 文件。</p><h2 id="你可以在本页完成什么" tabindex="-1">你可以在本页完成什么 <a class="header-anchor" href="#你可以在本页完成什么" aria-label="Permalink to &quot;你可以在本页完成什么&quot;">​</a></h2><ul><li>保存项目并查看未保存差异。</li><li>从项目草稿恢复未保存工作。</li><li>重新导入字幕并审查对齐变化。</li><li>保存旧版 CSV 或导出 XLSX。</li><li>配置并导出 SRT 或 ASS。</li></ul><h2 id="保存项目" tabindex="-1">保存项目 <a class="header-anchor" href="#保存项目" aria-label="Permalink to &quot;保存项目&quot;">​</a></h2><p>项目模式顶部按钮显示 <strong>保存项目</strong>；有未保存修改时显示星号。点击按钮或按 <code>Ctrl+S</code>（macOS：<code>Command+S</code>），当前字幕行会写入项目的 <code>workspace.csv</code>。</p><p>项目还会在项目文件夹中自动保存草稿，以及焦点行、播放位置、筛选、排序、列宽、时间轴缩放等工作区状态。自动草稿用于意外关闭后的恢复，不代替正式保存。</p><p>关闭或切换项目且存在未保存修改时，应用会要求保存、放弃或继续编辑。</p><h2 id="查看未保存的修改" tabindex="-1">查看未保存的修改 <a class="header-anchor" href="#查看未保存的修改" aria-label="Permalink to &quot;查看未保存的修改&quot;">​</a></h2><p>点击保存按钮旁的差异入口，打开 <strong>未保存差异</strong>：</p><p><img src="'+i+'" alt="未保存差异面板对比已保存版本和当前工作区"></p><ul><li><strong>已保存</strong>：上次正式保存的内容。</li><li><strong>当前</strong>：正在编辑的工作区。</li><li><strong>放弃所有修改</strong>：恢复到已保存版本。</li></ul><p>差异预览可能只显示部分修改行；摘要会说明是否还有未显示内容。保存后撤销历史仍可使用。</p><h2 id="恢复未保存的工作" tabindex="-1">恢复未保存的工作 <a class="header-anchor" href="#恢复未保存的工作" aria-label="Permalink to &quot;恢复未保存的工作&quot;">​</a></h2><p>重新打开项目时，如果项目草稿与保存基线匹配，应用会恢复草稿行。工作区状态还会恢复最近焦点和播放时间。</p><p>不要依赖清缓存保存工作。<strong>清除缓存并重启</strong>会删除应用拥有的本地缓存和旧句柄信息；项目文件夹中的正式文件和项目草稿仍是项目模式的主要恢复来源。</p><h2 id="重新导入字幕" tabindex="-1">重新导入字幕 <a class="header-anchor" href="#重新导入字幕" aria-label="Permalink to &quot;重新导入字幕&quot;">​</a></h2><ol><li>打开 <strong>项目设置</strong>。</li><li>导入新的原文或译文字幕。</li><li>选择 <strong>精确更新</strong> 或 <strong>整体替换</strong>。</li><li>检查映射。</li><li>审查字幕导入对齐。</li><li>确认导入。</li></ol><p><img src="'+s+'" alt="重新导入审查显示精确匹配、时间容差、拆分、合并和孤立项"></p><p>对齐审查可能显示：</p><ul><li><strong>精确匹配</strong>：时间完全相同。</li><li><strong>时间容差</strong>：边界偏移在允许范围内，使用导入时间。</li><li><strong>拆分</strong>：一条已有字幕对应多条导入字幕。</li><li><strong>合并</strong>：多条已有字幕对应一条导入字幕。</li><li><strong>孤立项</strong>：只存在于一侧，保留原行或作为新增行。</li></ul><p><strong>精确更新</strong>会执行上述对齐：更新原文时尽量保留匹配译文，更新译文时尽量保留原文。</p><p><strong>整体替换</strong>不执行对齐。它会整体重建本次映射到的每个分集，移除这些分集的旧行、另一轨道内容和现有编辑；本次没有匹配到的其他分集保持不变。该模式会清空原有撤销/重做历史。取消导入或对齐审查不会改变工作区。</p><h2 id="保存旧版-csv" tabindex="-1">保存旧版 CSV <a class="header-anchor" href="#保存旧版-csv" aria-label="Permalink to &quot;保存旧版 CSV&quot;">​</a></h2><p>旧版 CSV 模式提供 <strong>保存 CSV</strong> 或 <strong>另存为 CSV</strong>。应用会尽量保留原文件的：</p><ul><li>分隔符（分号或逗号）。</li><li>换行风格。</li><li>UTF-8 BOM。</li><li>引号策略。</li><li>CPS 的小数分隔符。</li></ul><p>如果重新打开同一文件且当前有未保存修改，应用会先询问是否另存当前工作或重新从磁盘打开。</p><h2 id="导出-xlsx" tabindex="-1">导出 XLSX <a class="header-anchor" href="#导出-xlsx" aria-label="Permalink to &quot;导出 XLSX&quot;">​</a></h2><p>在 <strong>旧版 → 导出 XLSX</strong> 中导出当前表格。若 CSV 有未保存修改，应用会先询问是否保存并导出；取消保存提示也会取消 XLSX 导出。</p><p>XLSX 是表格交付格式，不包含项目资源、视频或字幕样式。</p><h2 id="导出-srt-或-ass" tabindex="-1">导出 SRT 或 ASS <a class="header-anchor" href="#导出-srt-或-ass" aria-label="Permalink to &quot;导出 SRT 或 ASS&quot;">​</a></h2><p>项目模式点击顶部 <strong>导出</strong> 打开字幕导出向导。</p><p><img src="'+n+'" alt="字幕导出向导显示格式、内容、命名和检查区域"></p><ol><li>在 <strong>类型</strong> 中选择 SRT 或 ASS。</li><li>选择导出 <strong>译文</strong> 或 <strong>原文</strong>。</li><li>根据需要启用 <strong>双语</strong>。</li><li>选择输出文件夹。</li><li>设置文件名模板和集数格式。</li><li>检查文件名预览和 ASS 模板状态。</li><li>点击 <strong>导出</strong>。</li></ol><h2 id="设置-ass-样式" tabindex="-1">设置 ASS 样式 <a class="header-anchor" href="#设置-ass-样式" aria-label="Permalink to &quot;设置 ASS 样式&quot;">​</a></h2><p>导出 ASS 时选择：</p><ul><li><strong>源模板</strong>：复用导入 ASS/SSA 时保存的样式和头部。缺少对应集模板时无法导出。</li><li><strong>最小样式</strong>：使用应用内置的基础 ASS 样式，不读取源模板。</li></ul><p>如果原始素材是 SRT 或某集没有 ASS 模板，可以改用最小样式，或重新导入带模板的 ASS/SSA。</p><h2 id="设置输出内容和文件名" tabindex="-1">设置输出内容和文件名 <a class="header-anchor" href="#设置输出内容和文件名" aria-label="Permalink to &quot;设置输出内容和文件名&quot;">​</a></h2><ul><li><strong>字段</strong>：原文或译文。</li><li><strong>双语</strong>：把两个字段组合到输出字幕。</li><li><strong>输出文件夹</strong>：可位于项目文件夹内或外。</li><li><strong>文件名模板</strong>：使用 <code>{episode}</code> 占位，例如 <code>episode_{episode}</code>。</li><li><strong>分集位数/前导零</strong>：分集位数使用数字输入（1–4），新项目默认 2；勾选前导零后可显示为 <code>01</code>、<code>001</code> 等。已有项目保存的位数会保留。</li><li><strong>文件名预览</strong>：导出前检查每集实际文件名。</li></ul><p>如果多个集会生成同一路径，导出会被拒绝。已有文件会在写入前要求确认覆盖；批量写入失败时应用会尽量回滚已替换文件。</p><h2 id="处理导出限制" tabindex="-1">处理导出限制 <a class="header-anchor" href="#处理导出限制" aria-label="Permalink to &quot;处理导出限制&quot;">​</a></h2><p>项目字幕导出需要有效授权。未授权或授权过期时仍可打开导出向导并检查设置，但最终 <strong>导出</strong> 按钮不可用。前往 <strong>设置 → 授权</strong> 添加或更新授权，完整流程见<a href="./09-license-management.html">授权管理</a>。</p><p>导出不会修改工作区行、保存状态或撤销历史。</p><h2 id="遇到问题" tabindex="-1">遇到问题 <a class="header-anchor" href="#遇到问题" aria-label="Permalink to &quot;遇到问题&quot;">​</a></h2><ul><li><strong>保存按钮带星号</strong>：当前工作区与已保存版本不同；打开差异面板检查。</li><li><strong>重导入后行数变化</strong>：查看对齐审查中的拆分、合并和孤立项，不要在未检查时继续。</li><li><strong>ASS 导出按钮不可用</strong>：检查源模板缺失提示，或改用最小样式。</li><li><strong>导出按钮因授权禁用</strong>：打开授权管理，确认授权有效期、适用版本和机器是否匹配。参见<a href="./09-license-management.html#解决授权问题">解决授权问题</a>。</li><li><strong>文件名冲突</strong>：修改文件名模板，使每集路径包含唯一的 <code>{episode}</code>。</li></ul>',46)])])}const _=r(e,[["render",g]]);export{m as __pageData,_ as default};
